begin;

-- subagents: generated by `npm run guide:content` from content/guide/subagents.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 13,
  "outcome": "Вы поручаете исследование, ревью и тесты субагентам — помощникам со своим контекстом, — и основная сессия остаётся чистой для решений.",
  "blocks": [
    {
      "type": "text",
      "text": "Субагент — отдельный агент, которого запускает основная сессия. Он работает в своём контекстном окне: читает десятки файлов, гоняет команды, а обратно возвращает только выводы. Ваше окно не засоряется (шаг 2.4), а работа идёт параллельно."
    },
    {
      "type": "diagram",
      "name": "subagents",
      "caption": "Основная сессия держит план и решения. Субагенты читают и проверяют в своих окнах и приносят только итог."
    },
    {
      "type": "heading",
      "text": "Встроенные субагенты"
    },
    {
      "type": "list",
      "items": [
        "**Explore** — быстрый поиск и чтение кода, без права правки.",
        "**Plan** — исследование для режима планирования.",
        "**general-purpose** — универсальный помощник для многошаговых задач."
      ]
    },
    {
      "type": "text",
      "text": "Часто агент зовёт их сам. Но можно и прямо попросить: «Используй субагентов, чтобы найти все вызовы платёжного API и описать, где они различаются»."
    },
    {
      "type": "heading",
      "text": "Свой субагент"
    },
    {
      "type": "code",
      "file": ".claude/agents/reviewer.md",
      "code": "---\nname: reviewer\ndescription: Свежим взглядом проверяет diff перед коммитом. Используй после крупных правок.\ntools: Read, Glob, Grep\nmodel: sonnet\n---\n\nТы ревьюер. Прочитай изменения и найди ошибки корректности,\nослабленные тесты и нарушения требований задачи.\nОтмечай только то, что ломает поведение. Стиль не трогай.",
      "caption": "`tools` ограничивает субагента чтением: ревьюеру незачем править файлы. По `description` основной агент решает, когда его позвать."
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция сеанса: основная сессия поручает субагенту Explore найти все вызовы платёжного API, а субагенту reviewer — проверить готовый diff. Оба работают в своих окнах и возвращают короткие выводы.",
      "lines": [
        {
          "kind": "prompt",
          "text": "Субагентом найди все вызовы платёжного API, потом план миграции.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Explore: прочитано 46 файлов в своём окне"
        },
        {
          "kind": "info",
          "text": "Итог Explore: 7 вызовов, два — без обработки ошибок"
        },
        {
          "kind": "edit",
          "text": "src/payments/client.ts",
          "diff": "+38 −21"
        },
        {
          "kind": "prompt",
          "text": "Теперь пусть reviewer проверит diff.",
          "typed": true
        },
        {
          "kind": "info",
          "text": "reviewer: проблем корректности нет, один тест стоит усилить"
        },
        {
          "kind": "done",
          "text": "Готово. В основном окне — только выводы, а не 46 файлов."
        }
      ]
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Субагент тоже тратит лимиты",
      "text": "Каждый субагент делает свои запросы к модели. Пять субагентов на простой вопрос — лишний расход. Зовите их, когда задача действительно большая или нужен свежий взгляд."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Свежий взгляд — главное преимущество",
      "text": "Ревьюер-субагент не видит, как вы с агентом спорили о решении, — только код. Поэтому он замечает то, к чему автор уже привык (шаг 4.1)."
    }
  ],
  "practice": {
    "task": "Создайте в своём проекте субагента-ревьюера в `.claude/agents/` с доступом только на чтение. Дайте основной сессии задачу, а после правок попросите ревьюера проверить diff. Отдельно поручите Explore исследовательский вопрос о проекте.",
    "done": [
      "файл субагента лежит в `.claude/agents/` и закоммичен;",
      "ревьюер проверил реальный diff и нашёл или подтвердил что-то по делу;",
      "исследование прошло в субагенте, а основное окно осталось чистым."
    ]
  },
  "check": {
    "questions": [
      {
        "id": "why-subagent",
        "prompt": "Чем субагент полезнее, чем та же просьба в основной сессии?",
        "options": [
          {
            "id": "context",
            "text": "Он работает в своём окне и возвращает только выводы, не засоряя основной контекст."
          },
          {
            "id": "free",
            "text": "Он работает бесплатно."
          },
          {
            "id": "smarter",
            "text": "Он всегда умнее основной модели."
          }
        ]
      },
      {
        "id": "reviewer-tools",
        "prompt": "Какой набор `tools` лучше дать субагенту-ревьюеру?",
        "options": [
          {
            "id": "read-only",
            "text": "`Read, Glob, Grep` — только чтение."
          },
          {
            "id": "all",
            "text": "Все инструменты, включая правку и Bash."
          },
          {
            "id": "none",
            "text": "Никаких: пусть только думает."
          }
        ]
      },
      {
        "id": "when-not",
        "prompt": "Когда субагент скорее лишний?",
        "options": [
          {
            "id": "small",
            "text": "Чтобы найти одну функцию в известном файле."
          },
          {
            "id": "big-search",
            "text": "Чтобы прочитать полсотни файлов и найти закономерность."
          },
          {
            "id": "review",
            "text": "Чтобы свежим взглядом проверить большой diff."
          }
        ]
      }
    ]
  }
}$json$::jsonb where step_id = 'subagents';
insert into private.guide_checks (step_id, key) values ('subagents', $json${
  "why-subagent": {
    "correct": [
      "context"
    ],
    "why": {
      "context": "Да. Прочитанные им файлы остаются у него, а вы получаете итог.",
      "free": "Нет: субагент делает свои запросы к модели и расходует лимиты.",
      "smarter": "Не обязательно: польза — в отдельном контексте и фокусе, а не в уме."
    }
  },
  "reviewer-tools": {
    "correct": [
      "read-only"
    ],
    "why": {
      "read-only": "Да. Ревьюеру нужно читать, а не править: так он не «починит» найденное втихую.",
      "all": "Лишние права для задачи, где нужно только смотреть.",
      "none": "Без чтения файлов ревьюер не увидит код."
    }
  },
  "when-not": {
    "correct": [
      "small"
    ],
    "why": {
      "small": "Да. Быстрее спросить напрямую: субагент потратит запросы на то, что делается за секунду.",
      "big-search": "Как раз хороший случай: объём уйдёт в окно субагента.",
      "review": "Тоже хороший случай: ревьюеру полезен чистый контекст."
    }
  }
}$json$::jsonb)
on conflict (step_id) do update set key = excluded.key;

-- worktrees: generated by `npm run guide:content` from content/guide/worktrees.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 12,
  "outcome": "Вы ведёте несколько задач параллельно в разных сессиях, и они не мешают друг другу — каждая в своей рабочей копии.",
  "blocks": [
    {
      "type": "text",
      "text": "Две сессии Claude Code в одной папке — это два агента, которые правят одни и те же файлы. Чтобы вести задачи параллельно, каждой нужна своя рабочая копия. Git умеет это давно: worktree — отдельная папка с отдельной веткой из того же репозитория."
    },
    {
      "type": "command",
      "code": "claude --worktree promo",
      "caption": "Создаст `.claude/worktrees/promo/` на новой ветке и откроет в ней сессию. Короткая форма — `-w`."
    },
    {
      "type": "heading",
      "text": "Как это устроено"
    },
    {
      "type": "list",
      "items": [
        "**Отдельная папка и ветка**: правки одной сессии не видны другой, пока вы их не сольёте.",
        "**Уборка при выходе**: чистую рабочую копию Claude Code удалит сам, а с изменениями предложит оставить.",
        "**Вручную** тоже можно: `git worktree add ../shop-promo -b promo`, а потом `claude` в этой папке."
      ]
    },
    {
      "type": "session",
      "title": "два терминала",
      "summary": "Симуляция: в первом терминале агент работает в рабочей копии promo над промокодами, во втором — в копии reports над отчётами. Каждый правит свои файлы на своей ветке и прогоняет свои тесты.",
      "lines": [
        {
          "kind": "command",
          "text": "claude -w promo",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Рабочая копия .claude/worktrees/promo, своя ветка"
        },
        {
          "kind": "edit",
          "text": "src/cart/promo.ts",
          "diff": "+41"
        },
        {
          "kind": "command",
          "text": "claude -w reports   # во втором терминале",
          "typed": true
        },
        {
          "kind": "info",
          "text": "Рабочая копия .claude/worktrees/reports, своя ветка"
        },
        {
          "kind": "edit",
          "text": "src/reports/csv.ts",
          "diff": "+48"
        },
        {
          "kind": "pass",
          "text": "Тесты в обеих копиях проходят независимо"
        },
        {
          "kind": "done",
          "text": "Две задачи идут параллельно и не пересекаются."
        }
      ]
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Каждая копия — с нуля",
      "text": "Worktree — свежая выгрузка: `node_modules` и локальных файлов вроде `.env` там нет. Установите зависимости в каждой копии, а нужные игнорируемые файлы перечислите в `.worktreeinclude`. И следите за портами: два дев-сервера на одном порту не уживутся."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Курс, который вы читаете, так и делался",
      "text": "Лендинг и кабинет этого сайта разрабатывались параллельно: лендинг — в отдельной рабочей копии на своей ветке, кабинет — в основной. Две сессии агента ни разу не правили один файл одновременно."
    }
  ],
  "practice": {
    "task": "Возьмите две независимые задачи и запустите их в двух рабочих копиях: `claude -w <имя>` в двух терминалах. Доведите обе до коммита на своих ветках и слейте по очереди.",
    "done": [
      "обе задачи шли параллельно в своих рабочих копиях;",
      "в каждой копии установлены зависимости и проходят тесты;",
      "ветки слиты без конфликтов или конфликт разобран осознанно."
    ]
  },
  "check": {
    "questions": [
      {
        "id": "two-sessions",
        "prompt": "Вы хотите, чтобы два агента одновременно делали две разные задачи. Как избежать того, что они перетрут правки друг друга?",
        "options": [
          {
            "id": "worktree",
            "text": "Запустить каждую сессию в своей рабочей копии: `claude -w <имя>`."
          },
          {
            "id": "same-folder",
            "text": "Открыть две сессии в одной папке и попросить быть аккуратными."
          },
          {
            "id": "sequential",
            "text": "Только по очереди: параллельная работа невозможна."
          }
        ]
      },
      {
        "id": "fresh-copy",
        "prompt": "В новой рабочей копии не запускаются тесты: нет зависимостей и `.env`. Почему?",
        "options": [
          {
            "id": "fresh",
            "text": "Worktree — свежая выгрузка: игнорируемых файлов там нет, зависимости ставятся заново."
          },
          {
            "id": "broken",
            "text": "Worktree сломан, нужно пересоздать."
          },
          {
            "id": "symlink",
            "text": "Надо сделать ссылку на `node_modules` основной копии."
          }
        ]
      },
      {
        "id": "cleanup",
        "prompt": "Что произойдёт с рабочей копией, если выйти из сессии с незакоммиченными изменениями?",
        "options": [
          {
            "id": "ask",
            "text": "Claude Code предложит её оставить, чтобы работа не пропала."
          },
          {
            "id": "delete",
            "text": "Удалится вместе с изменениями."
          },
          {
            "id": "merge",
            "text": "Изменения сольются в main."
          }
        ]
      }
    ]
  }
}$json$::jsonb where step_id = 'worktrees';
insert into private.guide_checks (step_id, key) values ('worktrees', $json${
  "two-sessions": {
    "correct": [
      "worktree"
    ],
    "why": {
      "worktree": "Да. У каждой своя папка и ветка — правки не пересекаются.",
      "same-folder": "Оба агента правят одни и те же файлы — конфликты неизбежны.",
      "sequential": "Возможна — для этого и есть worktrees."
    }
  },
  "fresh-copy": {
    "correct": [
      "fresh"
    ],
    "why": {
      "fresh": "Да. Установите зависимости, а локальные файлы перечислите в `.worktreeinclude`.",
      "broken": "Он не сломан: так устроена любая свежая выгрузка репозитория.",
      "symlink": "Рискованно: зависимости веток могут различаться. Ставьте их в каждой копии."
    }
  },
  "cleanup": {
    "correct": [
      "ask"
    ],
    "why": {
      "ask": "Да. Чистые копии удаляются сами, а копии с изменениями — только с вашего согласия.",
      "delete": "Нет: копию с несохранённой работой молча не удаляют.",
      "merge": "Нет: слияние всегда остаётся вашим решением."
    }
  }
}$json$::jsonb)
on conflict (step_id) do update set key = excluded.key;

-- agent-roles: generated by `npm run guide:content` from content/guide/agent-roles.ts. Edit the source, not this file.
update public.guide_steps set lesson = $json${
  "minutes": 12,
  "outcome": "Вы раздаёте агентам роли — исследователь, исполнитель, ревьюер — так, чтобы они проверяли друг друга, а не подтверждали собственные ошибки.",
  "blocks": [
    {
      "type": "text",
      "text": "Один агент, который и исследует, и пишет, и проверяет себя, склонен соглашаться с собой. Роли разделяют эти задачи между разными контекстами: каждый агент видит только то, что нужно для его работы, и не знает, как спорили остальные."
    },
    {
      "type": "heading",
      "text": "Три роли"
    },
    {
      "type": "list",
      "items": [
        "**Исследователь** — читает код и документацию, собирает факты, ничего не правит. Подходит субагент Explore или свой с доступом только на чтение.",
        "**Исполнитель** — пишет код по плану и запускает проверки. Это обычно основная сессия.",
        "**Ревьюер** — видит только diff и требования, ищет расхождения. Свежий контекст здесь важнее всего."
      ]
    },
    {
      "type": "compare",
      "before": {
        "label": "Один на всё",
        "text": "Сделай миграцию платежей, напиши тесты и проверь, что всё правильно.",
        "note": "Агент проверяет собственные решения и тесты под собственный код — слепые пятна совпадают."
      },
      "after": {
        "label": "Роли",
        "text": "Субагент-исследователь: собери все вызовы API. Тесты напиши по требованиям, не глядя в реализацию. Потом пусть ревьюер в чистом контексте проверит diff.",
        "note": "Тесты не подогнаны под код, а ревьюер не знает, «как задумывалось», — только что получилось."
      }
    },
    {
      "type": "session",
      "title": "~/projects/shop",
      "summary": "Симуляция сеанса: исследователь собирает факты о платёжном API, исполнитель делает миграцию по плану, ревьюер в свежем контексте находит необработанный случай повторного списания. Исполнитель исправляет его, и проверки проходят.",
      "lines": [
        {
          "kind": "info",
          "text": "Исследователь: 7 вызовов API, 2 без обработки ошибок"
        },
        {
          "kind": "info",
          "text": "Исполнитель: миграция по плану, 3 файла"
        },
        {
          "kind": "edit",
          "text": "src/payments/client.ts",
          "diff": "+38 −21"
        },
        {
          "kind": "pass",
          "text": "npm test -- payments — пройдено"
        },
        {
          "kind": "info",
          "text": "Ревьюер: повторный вызов charge() при таймауте не защищён"
        },
        {
          "kind": "edit",
          "text": "src/payments/client.ts",
          "diff": "+6"
        },
        {
          "kind": "pass",
          "text": "Тест на повторный вызов добавлен и проходит"
        },
        {
          "kind": "done",
          "text": "Ошибку нашёл тот, кто не писал код."
        }
      ]
    },
    {
      "type": "heading",
      "text": "Соревнование гипотез"
    },
    {
      "type": "text",
      "text": "Для запутанного бага документация описывает приём: несколько агентов проверяют разные гипотезы параллельно и пытаются опровергнуть друг друга. Это защищает от «прилипания» к первой версии, которая пришла в голову."
    },
    {
      "type": "callout",
      "tone": "trap",
      "title": "Ревьюер не должен знать ответ",
      "text": "Если передать ревьюеру весь разговор с исполнителем, он унаследует те же допущения. Давайте ему только diff, требования и план."
    },
    {
      "type": "callout",
      "tone": "tip",
      "title": "Роли — не бюрократия",
      "text": "Для мелкой правки роли не нужны. Включайте их там, где ошибка дорогая (шаг 4.5): деньги, права, миграции."
    }
  ],
  "practice": {
    "task": "Возьмите задачу средней сложности и проведите её с тремя ролями: исследователь собирает факты, исполнитель пишет код, ревьюер в чистом контексте проверяет diff. Сравните, что нашёл ревьюер, с тем, что вы заметили бы сами.",
    "done": [
      "исследование и ревью шли в отдельных контекстах;",
      "ревьюер получил только diff, требования и план;",
      "вы знаете, нашёл ли ревьюер то, что пропустили исполнитель и вы."
    ]
  },
  "check": {
    "questions": [
      {
        "id": "reviewer-input",
        "prompt": "Что дать агенту-ревьюеру, чтобы ревью было полезным?",
        "options": [
          {
            "id": "diff-reqs",
            "text": "Diff, требования и план — без истории разговора с исполнителем."
          },
          {
            "id": "everything",
            "text": "Весь разговор: пусть знает, как задумывалось."
          },
          {
            "id": "nothing",
            "text": "Только название задачи."
          }
        ]
      },
